export function generateStarterWardrobe(userId: string): { items: ClothingItem[]; outfits: SavedOutfit[] } {
  const now = new Date().toISOString();

  const items: ClothingItem[] = STARTER_CLOTHING_ITEMS.map((item, index) => ({
    ...item,
    id: `item-${userId.substring(0, 8)}-${index + 1}`,
    user_id: userId,
    created_at: new Date(Date.now() - (12 - index) * 86400000 * 2).toISOString(),
    updated_at: now,
  }));

  // Create two starter outfits from the items
  const oxfordShirt = items.find((i) => i.name.includes('Oxford')) || items[0];
  const beigePants = items.find((i) => i.name.includes('Pleated')) || items[3];
  const trenchCoat = items.find((i) => i.name.includes('Trench')) || items[5];
  const whiteSneakers = items.find((i) => i.name.includes('Sneakers')) || items[6];
  const leatherBelt = items.find((i) => i.name.includes('Belt')) || items[9];
  const charcoalTee = items.find((i) => i.name.includes('Charcoal')) || items[1];
  const rawJeans = items.find((i) => i.name.includes('Jeans')) || items[2];
  const chelseaBoots = items.find((i) => i.name.includes('Boots')) || items[7];

  const outfits: SavedOutfit[] = [
    {
      id: `outfit-${userId.substring(0, 8)}-1`,
      user_id: userId,
      name: 'Autumn City Tailoring',
      description: 'Sophisticated modern tailored silhouette. Relaxed pleated trousers with crisp white oxford and deep forest trench.',
      occasion: 'Work',
      style: 'Minimalist',
      season: 'Fall',
      is_favorite: true,
      items: [
        { slot: 'top', clothing_item_id: oxfordShirt.id, item: oxfordShirt },
        { slot: 'bottom', clothing_item_id: beigePants.id, item: beigePants },
        { slot: 'outerwear', clothing_item_id: trenchCoat.id, item: trenchCoat },
        { slot: 'shoes', clothing_item_id: whiteSneakers.id, item: whiteSneakers },
        { slot: 'accessory', clothing_item_id: leatherBelt.id, item: leatherBelt },
      ],
      created_at: new Date(Date.now() - 4 * 86400000).toISOString(),
      updated_at: now,
    },
    {
      id: `outfit-${userId.substring(0, 8)}-2`,
      user_id: userId,
      name: 'Weekend Coffee & Gallery',
      description: 'Effortless casual pairing with structured raw denim, charcoal heavyweight tee, and rugged Chelsea boots.',
      occasion: 'Casual Outings',
      style: 'Casual',
      season: 'All-Season',
      is_favorite: true,
      items: [
        { slot: 'top', clothing_item_id: charcoalTee.id, item: charcoalTee },
        { slot: 'bottom', clothing_item_id: rawJeans.id, item: rawJeans },
        { slot: 'shoes', clothing_item_id: chelseaBoots.id, item: chelseaBoots },
        { slot: 'accessory', clothing_item_id: leatherBelt.id, item: leatherBelt },
      ],
      created_at: new Date(Date.now() - 7 * 86400000).toISOString(),
      updated_at: now,
    },
  ];

  return { items, outfits };
}
